      hakenStrobl: ['\\frac{d\\rho}{dt}=-\\frac{i}{\\hbar}[\\hat H,\\rho]-\\{\\hat\\Lambda,\\rho\\}+\\gamma\\sum_n\\Big(|n\\rangle\\langle n|\\rho|n\\rangle\\langle n|-\\tfrac12\\{|n\\rangle\\langle n|,\\rho\\}\\Big),\\qquad \\hat\\Lambda=\\frac{\\kappa}{2}|3\\rangle\\langle 3|+\\frac{\\Gamma}{2}\\hat 1', true],
