      singlet: ['\\hat P_S=\\tfrac14-\\hat{\\mathbf S}_1\\cdot\\hat{\\mathbf S}_2,\\qquad \\hat P_T=1-\\hat P_S', true],
      yield: ['\\Phi_S=\\frac1M\\sum_{m,n}\\big|\\langle m|\\hat P_S|n\\rangle\\big|^2\\frac{k^2}{k^2+\\omega_{mn}^2}', true],
      larmor: ['\\omega=\\gamma_eB,\\qquad \\frac{\\omega}{2\\pi}\\approx 28\\ \\mathrm{MHz\\,mT^{-1}}\\times 0.05\\ \\mathrm{mT}=1.4\\ \\mathrm{MHz}', true],
      marcus: ['k_{\\mathrm{ET}}=\\frac{2\\pi}{\\hbar}|H_{DA}|^2\\frac{1}{\\sqrt{4\\pi\\lambda k_BT}}\\exp\\Big[-\\frac{(\\Delta G^\\circ+\\lambda)^2}{4\\lambda k_BT}\\Big]', true],
      moser: ['|H_{DA}|^2\\propto e^{-\\beta R},\\qquad \\beta\\approx 1.4\\ \\text{Å}^{-1}', true],
      wkb: ['P\\approx\\exp\\Big[-\\frac{2}{\\hbar}\\int_{x_1}^{x_2}\\sqrt{2m\\big(V(x)-E\\big)}\\,dx\\Big]', true],
      bellP: ['P(E)=\\frac{1}{1+\\exp\\big[2\\pi(V-E)/h\\nu^\\ddagger\\big]},\\qquad Q=\\frac{k_{\\mathrm{quantum}}}{k_{\\mathrm{classical}}}=\\int_0^\\infty P(E)\\,e^{-(E-V)/k_BT}\\frac{dE}{k_BT}', true],
      bellQ: ['Q\\approx\\frac{u/2}{\\sin(u/2)},\\qquad u=\\frac{h\\nu^\\ddagger}{k_BT}<2\\pi', true],
      kie: ['\\frac{k_H}{k_D}\\approx\\exp\\Big[\\frac{hc(\\tilde\\nu_{\\mathrm{CH}}-\\tilde\\nu_{\\mathrm{CD}})}{2k_BT}\\Big]\\approx 7\\quad(298\\ \\mathrm K,\\ \\tilde\\nu_{\\mathrm{CH}}\\approx 2900\\ \\mathrm{cm^{-1}})', true],
      tautomer: ['K_{\\mathrm{taut}}=\\frac{[\\mathrm{G^*\\cdot C^*}]}{[\\mathrm{G\\cdot C}]}=e^{-\\Delta G/k_BT}', true],
      iets: ['\\varepsilon_D-\\varepsilon_A=\\hbar\\omega_{\\mathrm{vib}}', true],
      decoherence: ['\\tau_{\\mathrm{dec}}\\ll\\tau_{\\mathrm{dyn}}:\\qquad \\tau_{\\mathrm{dec}}\\sim10^{-20}\\text{–}10^{-13}\\ \\mathrm s,\\quad \\tau_{\\mathrm{dyn}}\\sim10^{-3}\\text{–}10^{-1}\\ \\mathrm s', true],
      lindblad: ['\\frac{d\\rho}{dt}=-\\frac{i}{\\hbar}[\\hat H,\\rho]+\\sum_k\\gamma_k\\Big(\\hat L_k\\rho\\hat L_k^\\dagger-\\tfrac12\\{\\hat L_k^\\dagger\\hat L_k,\\rho\\}\\Big)', true],
      drude: ['J(\\omega)=\\frac{2\\lambda\\,\\gamma\\,\\omega}{\\omega^2+\\gamma^2}', true],
